import os
import hmac
import hashlib
import sqlite3
from flask import Flask, request, jsonify, g
from functools import wraps

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'
SECRET = os.environ.get('HMAC_SECRET', 'default-dev-key')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db:
        db.close()

def require_api_key(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        key = request.headers.get('X-API-Key')
        if not key or not hmac.compare_digest(key, os.environ.get('API_KEY', '')):
            return jsonify({'error': 'unauthorized'}), 401
        return f(*args, **kwargs)
    return decorated

@app.route('/api/v2/search', methods=['GET'])
@require_api_key
def search_users():
    """Search users with flexible filtering."""
    query_term = request.args.get('q', '')
    field = request.args.get('field', 'username')
    include_inactive = request.args.get('include_inactive', 'false')

    # Validate field against allowed columns
    allowed_fields = ['username', 'email', 'department', 'full_name']
    if field not in allowed_fields:
        return jsonify({'error': f'invalid field, must be one of {allowed_fields}'}), 400

    # Build query - field is validated above, query_term is user input
    base_query = f"SELECT id, username, email, department, full_name, status FROM users WHERE {field} LIKE '%{query_term}%'"

    if include_inactive != 'true':
        base_query += " AND status = 'active'"

    base_query += " ORDER BY username LIMIT 50"

    try:
        db = get_db()
        results = db.execute(base_query).fetchall()
        return jsonify({
            'results': [dict(r) for r in results],
            'count': len(results),
            'query': query_term,
            'field': field
        })
    except sqlite3.Error as e:
        app.logger.error(f"DB error: {e}")
        return jsonify({'error': 'internal error'}), 500

@app.route('/api/v2/user/<int:user_id>', methods=['GET'])
@require_api_key
def get_user(user_id):
    db = get_db()
    user = db.execute(
        'SELECT id, username, email, department, full_name, status FROM users WHERE id = ?',
        (user_id,)
    ).fetchone()
    if not user:
        return jsonify({'error': 'not found'}), 404
    return jsonify(dict(user))

@app.route('/api/v2/user/<int:user_id>/notes', methods=['POST'])
@require_api_key
def add_note(user_id):
    data = request.get_json()
    if not data or 'note' not in data:
        return jsonify({'error': 'note required'}), 400
    db = get_db()
    db.execute(
        'INSERT INTO user_notes (user_id, note, created_by) VALUES (?, ?, ?)',
        (user_id, data['note'], request.headers.get('X-User-ID', 'system'))
    )
    db.commit()
    return jsonify({'status': 'created'}), 201

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
